import sys

def count_multiples(X, A, B, allowed_digits):
    def is_valid_number(num_str, allowed_digits):
        return all(digit in allowed_digits for digit in num_str)

    count = 0
    for i in range((A + X - 1) // X, B // X + 1):
        num = i * X
        if is_valid_number(str(num), allowed_digits):
            count += 1

    return count

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    X = int(data[0])
    A = int(data[1])
    B = int(data[2])
    allowed_digits = set(data[3])

    result = count_multiples(X, A, B, allowed_digits)
    print(result)
